rows=[]
for c in claims:
    status,rival,attacks,evidence,wording,remediation,drift=D[c['id']]
    # Source grounding remains explicit even when the only warranted judgment is normative.
    source=e('docs/'+c['doc'],c['loc'],'Exact audited proposition: '+c['text'])
    rows.append({'id':c['id'],'finalStatus':status,'kind':c['kind'],'rivalReading':rival,
        'attacks':attacks,'decisiveEvidence':[source]+evidence,
        'driftAtDocCommit':drift or common,'permittedWording':wording,'remediation':remediation})
assert len(rows)==50 and set(D)=={c['id'] for c in claims}
out=W/'audit-a-verification.jsonl'
out.write_text(''.join(json.dumps(r,ensure_ascii=False,separators=(',',':'))+'\n' for r in rows))
required={'id','finalStatus','kind','rivalReading','attacks','decisiveEvidence','driftAtDocCommit','permittedWording','remediation'}
valid={'ESTABLISHED','SUPPORTED','PLAUSIBLE','UNSUPPORTED','CONTESTED','REFUTED','UNDETERMINED','NON-EPISTEMIC'}
parsed=[json.loads(l) for l in out.read_text().splitlines()]
for r in parsed:
    assert set(r)==required and r['finalStatus'] in valid
    assert r['rivalReading'] and r['attacks'] and r['decisiveEvidence'] and r['permittedWording'] and r['remediation']
    for ev in r['decisiveEvidence']:
        assert Path(ev['path']).is_file(),ev
assert len({r['id'] for r in parsed})==50
print(out)
print('rows',len(parsed),'statuses',dict(Counter(r['finalStatus'] for r in parsed)))
print('main claim REFUTED',sum(r['finalStatus']=='REFUTED' for r in parsed))
print('main claim downgrade', 'C221 mapping incomplete: SUPPORTED; ambiguity clause independently ESTABLISHED')
print('attack verdict counts',dict(Counter(a['verdict'] for r in parsed for a in r['attacks'])))
print('Note: attack counts are scoped rival/premise rulings, not distinct atomized ledger claims.')
